// Minimal CJS shim for @deepseek-ai/dsh-llm/message (real package is ESM:
// "type":"module", lib/message.js is ESM — GraalJS standalone CommonJS
// require cannot load it). Surface copied verbatim from the dsh source:
//   packages/llm/llm/src/message.ts (isTokenDelta) + brand.ts (MessageId).
// Only the members the dsh plugins in this spike actually import are provided.

/** Provider/model identity — brand string (message.ts MessageId / brand.ts). */
function MessageId(id) { return id }

/**
 * Whether a stream chunk carries visible model output (the first-token
 * boundary shared by client step timing and the whole-log sessionStats
 * projection). Empty deltas (heartbeats, empty tool-call frames) do not count
 * as a first token.
 * @param chunk - the stream chunk to test.
 * @returns true when the chunk contains a non-empty text/reasoning/tool delta.
 */
function isTokenDelta(chunk) {
  switch (chunk.type) {
    case 'text-delta':
    case 'reasoning-delta':
      return chunk.text !== ''
    case 'tool-call-delta':
      return chunk.argumentsDelta !== '' || chunk.name !== undefined
    default:
      return false
  }
}

/** Create one identified user-role message and freeze it (message.ts:192-199). */
function createUserMessage(input) {
  const id = (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function')
    ? crypto.randomUUID()
    : ('shim-' + Math.random().toString(36).slice(2))
  const msg = Object.freeze({
    ...input,
    id: MessageId(id),
    role: 'user',
  })
  // 观测钩子:把每次创建的用户消息记到 globalThis,供 Java 测试断言插件注入的提醒。
  if (typeof globalThis !== 'undefined') {
    if (!Array.isArray(globalThis.__dshCreatedUserMessages)) globalThis.__dshCreatedUserMessages = []
    globalThis.__dshCreatedUserMessages.push(msg)
  }
  return msg
}

/** Detach and deep-freeze a message whose identity already exists (message.ts:169-171). */
function freezeMessage(message) {
  return Object.freeze(structuredClone(message))
}

module.exports = { MessageId, isTokenDelta, createUserMessage, freezeMessage }
